// 2. Detect Vendor & Validate
// Figures out which vendor sent the alarm (using the 'source' tag if present,
// falling back to structural field-signature matching), then checks that
// vendor's required raw fields are present.

const KNOWN_VENDORS = {
  'Huawei-U2000': ['neName', 'alarmName', 'severity', 'occurTime'],
  'Nokia-NFM-P': ['objectName', 'problemText', 'perceivedSeverity', 'eventTime'],
  'Cisco-EPNM': ['managedElement', 'faultDescription', 'faultSeverity', 'timeStamp'],
  'Juniper-JunosSpace': ['device-name', 'alarm-description', 'alarm-severity', 'alarm-time'],
  'FiberHome-iManagerU31': ['NEName', 'faultName', 'faultLevel', 'happenTime']
};

const STRUCTURAL_SIGNATURES = [
  { vendor: 'Huawei-U2000', keys: ['neName', 'alarmName', 'occurTime'] },
  { vendor: 'Nokia-NFM-P', keys: ['objectName', 'problemText', 'eventTime'] },
  { vendor: 'Cisco-EPNM', keys: ['managedElement', 'faultDescription', 'timeStamp'] },
  { vendor: 'Juniper-JunosSpace', keys: ['device-name', 'alarm-description', 'alarm-time'] },
  { vendor: 'FiberHome-iManagerU31', keys: ['NEName', 'faultName', 'happenTime'] }
];

function detectVendor(body) {
  if (body.source && KNOWN_VENDORS[body.source]) return body.source;
  for (const sig of STRUCTURAL_SIGNATURES) {
    if (sig.keys.every((k) => body[k] !== undefined)) return sig.vendor;
  }
  return null;
}

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.rawPayload ? item.json.rawPayload : (item.json.body ? item.json.body : item.json);
  const errors = [];

  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    errors.push('Input is missing or is not a valid JSON object.');
  }

  const vendor = body ? detectVendor(body) : null;

  if (!vendor) {
    errors.push(`Unable to detect vendor from payload. Supported vendors: ${Object.keys(KNOWN_VENDORS).join(', ')}`);
  } else {
    const requiredFields = KNOWN_VENDORS[vendor];
    const missing = requiredFields.filter((f) => body[f] === undefined || body[f] === null || body[f] === '');
    if (missing.length > 0) {
      errors.push(`Missing required fields for ${vendor}: ${missing.join(', ')}`);
    }
  }

  results.push({
    json: {
      isValid: errors.length === 0,
      vendor: vendor,
      validationErrors: errors,
      correlationIdIn: item.json.correlationId || null,
      rawPayload: body
    }
  });
}

return results;

// 3. Normalize Fields
// Maps each vendor's own field names into the 10 standard fields required
// by this milestone: vendor, alarmId, nodeName, alarmName, alarmType,
// severity, timestamp, region, siteId, status.

function detectAlarmType(rawText) {
  const text = (rawText || '').toLowerCase();
  if (text.includes('fiber cut') || text.includes('fibre cut') || text.includes('fiber break')) return 'FIBER_CUT';
  if (text.includes('loss of signal') || text.includes('los alarm') || text === 'los') return 'LOS';
  if (text.includes('loss of frame') || text.includes('lof alarm') || text === 'lof') return 'LOF';
  if (text.includes('bit error rate') || text.includes('high ber')) return 'HIGH_BER';
  if (text.includes('attenuation')) return 'HIGH_ATTENUATION';
  if (text.includes('otn port')) return 'OTN_PORT_DOWN';
  if (text.includes('dwdm')) return 'DWDM_CARD_FAILURE';
  if (text.includes('mux') || text.includes('multiplexer')) return 'MUX_FAILURE';
  if (text.includes('power')) return 'POWER_FAILURE';
  if (text.includes('node down') || text.includes('device unreachable')) return 'SITE_DOWN';
  if (text.includes('site') && (text.includes('down') || text.includes('unreachable'))) return 'SITE_DOWN';
  if (text.includes('link down') || text.includes('interface down') || text.includes('ethernet link')) return 'LINK_DOWN';
  if (text.includes('temperature')) return 'TEMPERATURE_ALARM';
  return 'OTHER';
}

function normalizeSeverity(rawSeverity) {
  const s = (rawSeverity || '').toString().toUpperCase();
  if (s.includes('CRIT')) return 'Critical';
  if (s.includes('MAJOR')) return 'Major';
  if (s.includes('MINOR')) return 'Minor';
  if (s.includes('WARN')) return 'Warning';
  return 'Warning';
}

function toIsoUtc(dateStr) {
  if (!dateStr) return null;
  const trimmed = dateStr.toString().trim();
  if (/Z$|[+-]\d{2}:\d{2}$/.test(trimmed)) {
    return new Date(trimmed).toISOString();
  }
  const isoLike = trimmed.replace(' ', 'T') + '+06:00';
  return new Date(isoLike).toISOString();
}

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.rawPayload;
  const vendor = item.json.vendor;
  let mapped = {};

  switch (vendor) {
    case 'Huawei-U2000':
      mapped = { alarmId: body.alarmId || null, nodeName: body.neName, alarmNameRaw: body.alarmName, severityRaw: body.severity, timestampRaw: body.occurTime, region: body.location || null };
      break;
    case 'Nokia-NFM-P':
      mapped = { alarmId: body.alarmRef || null, nodeName: body.objectName, alarmNameRaw: body.problemText, severityRaw: body.perceivedSeverity, timestampRaw: body.eventTime, region: body.siteName || null };
      break;
    case 'Cisco-EPNM':
      mapped = { alarmId: body.eventId || null, nodeName: body.managedElement, alarmNameRaw: body.faultDescription, severityRaw: body.faultSeverity, timestampRaw: body.timeStamp, region: body.deviceLocation || null };
      break;
    case 'Juniper-JunosSpace':
      mapped = { alarmId: body.alarmId || null, nodeName: body['device-name'], alarmNameRaw: body['alarm-description'], severityRaw: body['alarm-severity'], timestampRaw: body['alarm-time'], region: body.site || null };
      break;
    case 'FiberHome-iManagerU31':
      mapped = { alarmId: body.alarmSerial || null, nodeName: body.NEName, alarmNameRaw: body.faultName, severityRaw: body.faultLevel, timestampRaw: body.happenTime, region: body.region || null };
      break;
    default:
      mapped = { alarmId: null, nodeName: null, alarmNameRaw: null, severityRaw: null, timestampRaw: null, region: null };
  }

  results.push({
    json: {
      vendor: vendor,
      alarmId: mapped.alarmId,
      nodeName: mapped.nodeName,
      siteId: mapped.nodeName,
      alarmName: mapped.alarmNameRaw,
      alarmType: detectAlarmType(mapped.alarmNameRaw),
      severity: normalizeSeverity(mapped.severityRaw),
      timestamp: toIsoUtc(mapped.timestampRaw),
      region: mapped.region,
      status: 'New',
      correlationIdIn: item.json.correlationIdIn,
      rawPayload: body
    }
  });
}

return results;

// 4. Ensure Correlation ID
// Keeps the correlationId if the calling workflow (WF-01) already assigned
// one; generates a new UUID only if it is missing.

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

return $input.all().map((item) => {
  const { correlationIdIn, ...rest } = item.json;
  return {
    json: {
      correlationId: correlationIdIn || generateUUID(),
      ...rest
    }
  };
});
